package com.kayoyak.demoapp.data.chat

import kotlinx.serialization.Serializable

/** Who produced a message. */
@Serializable
enum class MessageRole {
    USER,
    ASSISTANT,
}

/**
 * One turn of a conversation.
 *
 * [modelId] records which model produced an assistant message rather than
 * looking it up later. A conversation can outlive the model that started it,
 * and a reply that was generated by a 360M model should not be presented as
 * though a 1.7B one produced it.
 */
@Serializable
data class ChatMessage(
    val id: String,
    val role: MessageRole,
    val text: String,
    val createdAt: Long,
    val modelId: String? = null,
    /** Generation time for assistant messages. Displayed so quality has context. */
    val elapsedMillis: Long? = null,
    /**
     * How many tokens came back, for assistant messages.
     *
     * Optional with a default so a conversation written before this existed still
     * parses. Stored rather than recomputed because the count is what the runtime
     * actually produced: re-deriving it from the text would give a different number
     * for the same reply, and the point of showing it is to compare models.
     */
    val tokenCount: Int? = null,
    /**
     * True when the user stopped generation part-way.
     *
     * Kept so a partial reply is not mistaken for a complete one on reopening.
     */
    val interrupted: Boolean = false,
    /**
     * The model's reasoning, for a reply from a reasoning model.
     *
     * Stored rather than shown once and forgotten. It is the only evidence that
     * separates a model that misunderstood the question from one that understood it
     * and got the answer wrong, and that distinction is the whole reason to ask
     * again rather than give up.
     *
     * Optional with a default so a conversation written before this existed still
     * parses.
     */
    val reasoning: String? = null,
    /**
     * Every version of this reply, oldest first, with [versionIndex] selecting the
     * one in [text].
     *
     * Empty for a reply that has never been regenerated. That case is not the same
     * as a one-element list: an empty list means the field has never been used, and
     * treating it as `listOf(text)` would make every ordinary reply carry a version
     * history it does not have.
     *
     * Regenerating used to delete the previous answer -- from the transcript and
     * from disk, with nothing to undo it. Keeping it costs a few hundred bytes and
     * removes the only irreversible thing on this screen. A wrong answer is not
     * always immediately recognisable as wrong, and the one before it is often the
     * one that was right.
     */
    /**
     * When the user marked this as worth keeping, or null.
     *
     * A bookmark, not a pin. Pinning is about a whole conversation and it changes
     * where that conversation sits in the list; this is about one answer inside
     * one conversation, and the point is to be able to find it again without
     * reading the whole thing.
     */
    val keptAt: Long? = null,
    val versions: List<String> = emptyList(),
    /** Index of [text] within [versions]. Meaningless when [versions] is empty. */
    val versionIndex: Int = 0,
    /**
     * How long until the first token appeared.
     *
     * The wait before anything happens, which grows with the length of the
     * conversation. Separate from [decodeTokensPerSecond] because they are
     * different complaints with opposite fixes.
     */
    val timeToFirstTokenMillis: Long? = null,
    /** How fast the answer arrived, once it started. */
    val decodeTokensPerSecond: Double? = null,
)

/**
 * A conversation and its history.
 *
 * Stored as one file per conversation. [title] is derived from the first user
 * message so a list of conversations is readable without opening each one.
 */
@Serializable
data class Conversation(
    val id: String,
    val title: String,
    val modelId: String,
    val createdAt: Long,
    val updatedAt: Long,
    val messages: List<ChatMessage> = emptyList(),
    /**
     * When this was pinned, or null.
     *
     * A timestamp rather than a boolean, because the useful question about a
     * pinned conversation is which one was pinned first — that is the order they
     * are shown in, and a flag cannot answer it.
     *
     * Optional with a default so a file written before this existed still parses.
     * A history screen that refused to open because one field was missing would
     * lose exactly the conversations a user cares about most.
     */
    val pinnedAt: Long? = null,
    /**
     * When this was put away, or null for one that is in the list.
     *
     * Not the same as [pinnedAt], and not the same as deleting. A pinned
     * conversation is one the user wants to hand; an archived one is one they do
     * not want to look at but are not ready to lose. Without it the only way to
     * tidy a long list is to delete, and deleting is irreversible.
     *
     * Optional with a default so a file written before this existed still parses.
     */
    val archivedAt: Long? = null,
) {
    companion object {
        /**
         * Longest title kept, in characters.
         *
         * Enough for a short question, short enough not to wrap in a list row.
         */
        const val MAX_TITLE_LENGTH = 60
        /**
         * What a conversation is called before its first question names it.
         *
         * Chinese because the app is. This is what the history list shows for the
         * moment between opening a new chat and typing into it, and a leftover
         * English word there is the kind of thing nobody notices until a user does.
         */
        const val UNNAMED = "新对话"

        /** Derives a list-friendly title from the first thing the user said. */
        fun titleFrom(firstUserMessage: String): String {
            val collapsed = firstUserMessage.trim().replace(Regex("\\s+"), " ")
            // Only reached when the first message is blank, which the chat screen
            // does not allow. Chinese because the app is, and because a leftover
            // English word is the kind of thing nobody notices until a user does.
            if (collapsed.isEmpty()) return UNNAMED
            return if (collapsed.length <= MAX_TITLE_LENGTH) {
                collapsed
            } else {
                collapsed.take(MAX_TITLE_LENGTH - 1).trimEnd() + "\u2026"
            }
        }
    }
}

/**
 * A reply carrying one more version, selected.
 *
 * The only way [versions] grows, and it keeps [versionIndex] pointing at [text].
 * Nothing else may set the three together: a version list that disagrees with the
 * text it is supposed to select is a reply that shows one answer and offers
 * another, and there is no way for a reader to tell which one the model was given.
 */
fun ChatMessage.withNewVersion(newText: String, at: Long): ChatMessage {
    val all = (if (versions.isEmpty()) listOf(text) else versions) + newText
    return copy(text = newText, versions = all, versionIndex = all.lastIndex, createdAt = at)
}

/**
 * The same reply showing version [index].
 *
 * Out-of-range and empty are no-ops rather than errors: this is reached from a
 * button, and a reply that was already replaced underneath the tap should do
 * nothing rather than throw.
 */
fun ChatMessage.withVersion(index: Int): ChatMessage =
    if (versions.isEmpty() || index !in versions.indices) {
        this
    } else {
        copy(text = versions[index], versionIndex = index)
    }

/**
 * Marks a message as worth keeping, or stops.
 *
 * [at] is passed in rather than read from the clock so a test can decide what time
 * it is, and so a caller that has already stamped a conversation does not stamp
 * the message with a second, slightly later time.
 */
fun ChatMessage.withKeeping(keep: Boolean, at: Long): ChatMessage =
    copy(keptAt = if (keep) at else null)